import { cn } from '@cascivo/core/pure'
import type { HTMLAttributes, ReactNode } from 'react'
import styles from './visually-hidden.module.css'

export interface VisuallyHiddenProps extends HTMLAttributes<HTMLSpanElement> {
  children: ReactNode
}

export function VisuallyHidden({ children, className, ...props }: VisuallyHiddenProps) {
  return (
    <span className={cn(styles['visuallyHidden'], className)} {...props}>
      {children}
    </span>
  )
}

@layer cascivo.component {
  .visuallyHidden {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'VisuallyHidden',
  description: 'Hides content visually while keeping it available to screen readers',
  category: 'display',
  clientJs: 'none',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'children',
      type: 'ReactNode',
      required: true,
      description: 'Content announced by assistive technology but not painted',
    },
  ],
  tokens: [],
  accessibility: {
    role: 'none',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    {
      title: 'Icon button label',
      code: '<button type="button"><CloseIcon /><VisuallyHidden>Close dialog</VisuallyHidden></button>',
      description: 'Gives an icon-only control an accessible name',
    },
    {
      title: 'Table context',
      code: '<th>Price <VisuallyHidden>(in euros)</VisuallyHidden></th>',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['accessibility', 'screen-reader', 'sr-only', 'hidden'],
  intent: {
    whenToUse: [
      'Giving an icon-only control an accessible name without showing text',
      'Adding screen-reader-only context that would be redundant visually',
      'Providing off-screen labels for tables, links, or form controls',
    ],
    whenNotToUse: [
      'Hiding content from everyone — use hidden or display:none',
      'Temporarily hiding then revealing UI — use conditional rendering',
    ],
    antiPatterns: [
      {
        bad: 'Wrapping decorative content in VisuallyHidden to "clean up" the layout',
        good: 'aria-hidden on decorative elements; VisuallyHidden only for content screen readers need',
        why: 'VisuallyHidden keeps content in the accessibility tree — using it to hide noise pollutes screen-reader output',
      },
    ],
    related: [
      {
        name: 'SkipNav',
        relationship: 'alternative',
        reason: 'SkipNav uses a similar hidden-until-focused technique for skip links',
      },
    ],
    a11yRationale:
      'Applies the standard clip technique so content stays in the DOM and accessibility tree while being painted off-screen — assistive tech reads it, sighted users do not see it',
    content: {
      // Children are the page's authored prose, not chrome this component owns —
      // so `audit --ai`'s raw-string rule must not flag every sentence.
      contentPrimitive: true,
      tone: 'Concise supplementary context for screen readers',
      notes: 'Write what a screen-reader user needs that visuals already convey',
    },
    flexibility: [
      {
        area: 'children',
        level: 'flexible',
        note: 'Any text/content meant for assistive tech',
      },
      {
        area: 'visibility technique',
        level: 'strict',
        note: 'Must keep content in the a11y tree — never display:none',
      },
    ],
  },
}
